import re

def json_pointer(doc, pointer: str):
    if pointer == '':
        return doc
    if not pointer.startswith('/'):
        raise ValueError("JSON pointer must start with '/'")

    def decode(token):
        out = []
        i = 0
        while i < len(token):
            c = token[i]
            if c == '~':
                if i + 1 >= len(token):
                    raise ValueError("Invalid '~' escape")
                nxt = token[i + 1]
                if nxt == '0':
                    out.append('~')
                elif nxt == '1':
                    out.append('/')
                else:
                    raise ValueError("Invalid '~' escape")
                i += 2
            else:
                out.append(c)
                i += 1
        return ''.join(out)

    current = doc
    for token in pointer[1:].split('/'):
        key = decode(token)

        if isinstance(current, dict):
            if key not in current:
                raise ValueError(f"Missing key: {key!r}")
            current = current[key]

        elif isinstance(current, list):
            if not re.fullmatch(r'(0|[1-9][0-9]*)', key):
                raise ValueError(f"Invalid list index: {key!r}")
            idx = int(key)
            if idx < 0 or idx >= len(current):
                raise ValueError(f"List index out of range: {idx}")
            current = current[idx]

        else:
            raise ValueError("Cannot index into non-container")

    return current
